class Solution {
public:
    std::vector<int> kthSmallestPathXor(int n, std::vector<std::vector<int>>& edges, std::vector<int>& values, std::vector<std::vector<int>>& queries) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        std::vector<int> ans;
        ans.reserve(queries.size());

        for (const auto& q : queries) {
            int start = q[0], target = q[1], k = q[2];
            std::vector<int> parent(n, -2);
            parent[start] = -1;
            std::queue<int> qu;
            qu.push(start);

            while (!qu.empty()) {
                int u = qu.front();
                qu.pop();
                if (u == target) break;
                for (int v : adj[u]) {
                    if (parent[v] == -2) {
                        parent[v] = u;
                        qu.push(v);
                    }
                }
            }

            std::vector<int> path;
            int curr = target;
            while (curr != -1) {
                path.push_back(curr);
                curr = parent[curr];
            }
            std::reverse(path.begin(), path.end());

            int m = path.size();
            std::vector<int> xor_sums;
            xor_sums.reserve(m * (m + 1) / 2);

            for (int i = 0; i < m; ++i) {
                int run = 0;
                for (int j = i; j < m; ++j) {
                    run ^= values[path[j]];
                    xor_sums.push_back(run);
                }
            }

            std::sort(xor_sums.begin(), xor_sums.end());
            if (k <= (int)xor_sums.size()) {
                ans.push_back(xor_sums[k - 1]);
            } else {
                ans.push_back(-1);
            }
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] kthSmallestPathXor(int n, int[][] edges, int[] values, int[][] queries) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] ans = new int[queries.length];
        for (int qIdx = 0; qIdx < queries.length; qIdx++) {
            int start = queries[qIdx][0], target = queries[qIdx][1], k = queries[qIdx][2];
            int[] parent = new int[n];
            Arrays.fill(parent, -2);
            parent[start] = -1;

            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(start);

            while (!queue.isEmpty()) {
                int u = queue.poll();
                if (u == target) break;
                for (int v : adj.get(u)) {
                    if (parent[v] == -2) {
                        parent[v] = u;
                        queue.add(v);
                    }
                }
            }

            List<Integer> path = new ArrayList<>();
            int curr = target;
            while (curr != -1) {
                path.add(curr);
                curr = parent[curr];
            }
            Collections.reverse(path);

            int m = path.size();
            List<Integer> xorSums = new ArrayList<>(m * (m + 1) / 2);

            for (int i = 0; i < m; i++) {
                int run = 0;
                for (int j = i; j < m; j++) {
                    run ^= values[path.get(j)];
                    xorSums.add(run);
                }
            }

            Collections.sort(xorSums);
            if (k <= xorSums.size()) {
                ans[qIdx] = xorSums.get(k - 1);
            } else {
                ans[qIdx] = -1;
            }
        }

        return ans;
    }
}

