var kthSmallestPathXor = function(n, edges, values, queries) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const ans = [];
    for (const [start, target, k] of queries) {
        const parent = new Int32Array(n).fill(-2);
        parent[start] = -1;
        const queue = [start];

        let head = 0;
        while (head < queue.length) {
            const u = queue[head++];
            if (u === target) break;
            for (const v of adj[u]) {
                if (parent[v] === -2) {
                    parent[v] = u;
                    queue.push(v);
                }
            }
        }

        const path = [];
        let curr = target;
        while (curr !== -1) {
            path.push(curr);
            curr = parent[curr];
        }
        path.reverse();

        const m = path.length;
        const xorSums = [];

        for (let i = 0; i < m; i++) {
            let run = 0;
            for (let j = i; j < m; j++) {
                run ^= values[path[j]];
                xorSums.push(run);
            }
        }

        xorSums.sort((a, b) => a - b);
        if (k <= xorSums.length) {
            ans.push(xorSums[k - 1]);
        } else {
            ans.push(-1);
        }
    }

    return ans;
};
